VALUES ('vid_7a3f91', 'usr_creator_11', 'Distributed Systems Patterns', 'UPLOADING', 's3://origstore-prod/7a3f/vid_7a3f91/source.mov', NOW)
ON CONFLICT (id) DO NOTHING;

// concurrency-capped parallel PUT
const pool = new WorkerPool(5)
for (const part of session.parts) { pool.submit(async => { const body = await file.slice((part.partNumber-1)*part.size, part.partNumber*part.size) const resp = await fetch(part.signedUrl, { method: "PUT", body, headers: {"Content-Length": part.size} }) etags[part.partNumber] = resp.headers.get("ETag") }, {retries: 3, backoff: "exponential"})
}
await pool.drain

# idempotent transition
UPDATE videos
SET status='TRANSCODING', source_size_bytes=327155712
WHERE id='vid_7a3f91' AND status='UPLOADING'; # backup kickoff (idempotent on video_id)
kafka.produce( topic="upload-ready", key="vid_7a3f91", value={ "video_id": "vid_7a3f91", "source_ref": "s3://origstore-prod/7a3f/vid_7a3f91/source.mov", "size_bytes": 327155712, "owner_id": "usr_creator_11", "ts": "2026-04-24T10:12:35Z" }
) return 202, {"status": "TRANSCODING", "video_id": "vid_7a3f91"}

